import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

@Timeout(value = 35, unit = TimeUnit.SECONDS)
class TimeLimitIterationLaunchFailureTest {

	@Test
	void rejectedCancellationLaunchDoesNotRunCallbackOnSignalThread() throws Exception {
		ControlledSource source = new ControlledSource();
		source.releasePull.countDown();
		source.releaseClose.countDown();
		AtomicInteger launches = new AtomicInteger();
		TimeLimitIteration.AsyncLauncher launcher = task -> {
			if (launches.incrementAndGet() == 1)
				throw new RejectedExecutionException("first cancellation launch");
			Thread.startVirtualThread(task);
		};
		RuntimeException timeout = new IllegalStateException("timed out");
		TimeLimitIteration<String> limited = timed(source, launcher, timeout);
		try (var workers = Executors.newSingleThreadExecutor();
				AutoCloseable cleanup = () -> {
					source.releaseAll();
					limited.close();
				}) {
			Future<?> signal = workers.submit(limited::interrupt);
			assertTrue(source.callbackEntered.await(10, TimeUnit.SECONDS));
			assertDoesNotThrow(() -> signal.get(3, TimeUnit.SECONDS),
					"the signal thread must not execute the blocked cancellation callback");
			assertEquals(1, source.releaseCallback.getCount());
			source.releaseCallback.countDown();
			assertTrue(source.closeEntered.await(10, TimeUnit.SECONDS));
			assertEquals(1, source.requests.get());
			assertEquals(1, source.closes.get());
		}
		assertEquals(1, source.requests.get());
		assertEquals(1, source.closes.get());
	}

	@Test
	void rejectedCleanupLaunchDoesNotBlockTheTimedOutReadCaller() throws Exception {
		ControlledSource source = new ControlledSource();
		source.releaseCallback.countDown();
		CountDownLatch firstTaskFinished = new CountDownLatch(1);
		AtomicInteger launches = new AtomicInteger();
		TimeLimitIteration.AsyncLauncher launcher = task -> {
			int index = launches.incrementAndGet();
			if (index == 2)
				throw new RejectedExecutionException("cleanup launch");
			Thread.startVirtualThread(() -> {
				try {
					task.run();
				} finally {
					if (index == 1)
						firstTaskFinished.countDown();
				}
			});
		};
		RuntimeException timeout = new IllegalStateException("timed out");
		TimeLimitIteration<String> limited = timed(source, launcher, timeout);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					source.releaseAll();
					limited.close();
				}) {
			Future<Boolean> pull = workers.submit(limited::hasNext);
			assertTrue(source.pullEntered.await(10, TimeUnit.SECONDS));
			limited.interrupt();
			assertTrue(firstTaskFinished.await(10, TimeUnit.SECONDS),
					"accepted cancellation must finish before pull release");
			source.releasePull.countDown();
			assertTrue(source.closeEntered.await(10, TimeUnit.SECONDS), "the injected cleanup path must be reached");
			ExecutionException failure = assertThrows(ExecutionException.class, () -> pull.get(3, TimeUnit.SECONDS),
					"timeout must reach its caller while source cleanup remains blocked");
			assertSame(timeout, failure.getCause());
			assertEquals(1, source.releaseClose.getCount());
			source.releaseClose.countDown();
		}
		assertEquals(1, source.requests.get());
		assertEquals(1, source.closes.get());
	}

	@Test
	void launcherThatStartsCleanupThenThrowsDoesNotCloseTwice() throws Exception {
		ControlledSource source = new ControlledSource();
		source.releaseCallback.countDown();
		CountDownLatch firstTaskFinished = new CountDownLatch(1);
		CountDownLatch secondLaunchThrowing = new CountDownLatch(1);
		AtomicInteger launches = new AtomicInteger();
		TimeLimitIteration.AsyncLauncher launcher = task -> {
			int index = launches.incrementAndGet();
			if (index == 1) {
				Thread.startVirtualThread(() -> {
					try {
						task.run();
					} finally {
						firstTaskFinished.countDown();
					}
				});
			} else if (index == 2) {
				Thread.startVirtualThread(task);
				await(source.closeEntered);
				secondLaunchThrowing.countDown();
				throw new RejectedExecutionException("cleanup started before failure");
			} else {
				Thread.startVirtualThread(task);
			}
		};
		RuntimeException timeout = new IllegalStateException("timed out");
		TimeLimitIteration<String> limited = timed(source, launcher, timeout);
		try (var workers = Executors.newFixedThreadPool(2);
				AutoCloseable cleanup = () -> {
					source.releaseAll();
					limited.close();
				}) {
			Future<Boolean> pull = workers.submit(limited::hasNext);
			assertTrue(source.pullEntered.await(10, TimeUnit.SECONDS));
			limited.interrupt();
			assertTrue(firstTaskFinished.await(10, TimeUnit.SECONDS));
			source.releasePull.countDown();
			assertTrue(secondLaunchThrowing.await(10, TimeUnit.SECONDS),
					"the started-then-thrown path must be reached");
			ExecutionException failure = assertThrows(ExecutionException.class, () -> pull.get(10, TimeUnit.SECONDS),
					"the timed-out pull must finish while the original source close is held");
			assertSame(timeout, failure.getCause());
			assertEquals(1, source.releaseClose.getCount(), "the original source close is still held");
			assertEquals(1, source.duplicateClose.getCount(), "no duplicate close may start before the pull returns");
			assertEquals(1, source.closes.get());
			source.releaseClose.countDown();
		}
		assertEquals(1, source.requests.get());
		assertEquals(1, source.closes.get());
	}

	private static TimeLimitIteration<String> timed(ControlledSource source,
			TimeLimitIteration.AsyncLauncher launcher, RuntimeException timeout) {
		return new TimeLimitIteration<>(source, 60_000, launcher) {
			@Override
			protected void throwInterruptedException() {
				throw timeout;
			}
		};
	}

	private static final class ControlledSource implements CloseableIteration<String>, CooperativeCancellation {
		final CountDownLatch pullEntered = new CountDownLatch(1), releasePull = new CountDownLatch(1);
		final CountDownLatch callbackEntered = new CountDownLatch(1), releaseCallback = new CountDownLatch(1);
		final CountDownLatch closeEntered = new CountDownLatch(1), releaseClose = new CountDownLatch(1);
		final CountDownLatch duplicateClose = new CountDownLatch(1);
		final AtomicInteger requests = new AtomicInteger(), closes = new AtomicInteger();

		@Override
		public boolean hasNext() {
			pullEntered.countDown();
			await(releasePull);
			return true;
		}

		@Override
		public String next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			requests.incrementAndGet();
			callbackEntered.countDown();
			await(releaseCallback);
			return true;
		}

		@Override
		public void close() {
			if (closes.incrementAndGet() > 1)
				duplicateClose.countDown();
			closeEntered.countDown();
			await(releaseClose);
		}

		void releaseAll() {
			releasePull.countDown();
			releaseCallback.countDown();
			releaseClose.countDown();
		}
	}

	private static void await(CountDownLatch latch) {
		boolean interrupted = false;
		while (true)
			try {
				latch.await();
				break;
			} catch (InterruptedException e) {
				interrupted = true;
			}
		if (interrupted)
			Thread.currentThread().interrupt();
	}
}
